  border-top: transparent;
  border-right: transparent;
  border-bottom: gray 2px solid;
  border-radius: 0px;
  font-family: "Brandon Grotesque W01 Regular",sans-serif;
  font-style: italic;
  font-size: 20px;
  padding: 10px;
}

.ct-012e9b2f .modal--email .form-wrapper label {
  color: #4d4d4d;
  font-family: "Brandon Grotesque W01 Regular",sans-serif;
  font-size: 16px;
  margin: 0;
}

.ct-012e9b2f .modal--email .form-wrapper input[type=checkbox] {
  margin: 0 10px 0 0 !important;
}

.ct-012e9b2f .modal--email .form-wrapper .two-column {
  display: flex;
  column-gap: 20px;
}

.ct-012e9b2f .modal--email .form-wrapper .two-column input {
  width: 50%;
}

.ct-012e9b2f .modal--email .form-wrapper input:not(input[type=submit]):focus {
    color: #495057;
    background-color: #fff;
    border-color: #80bdff;
    outline: 0;
    box-shadow: 0 0 0 0.2rem rgba(0,123,255,0.25);
}

.ct-012e9b2f .modal--email .form-wrapper input[type=submit] {
    width: 100%;
    height: 42px;
    border: #7d3269 2px solid;
    color: #7d3269;
    background: transparent;
    font-size: 18px;
    padding: 0 10px;
    font-family: "Brandon Grotesque W01 Bold",sans-serif;
}

.ct-012e9b2f .modal--email .form-wrapper input[type=submit]:hover {
    color: #fff;
    background-color: #7D3269;
    cursor: pointer;
}

